//! Threads core (m.thread, spec v1.4+: MSC3440 relations, MSC3771 threaded receipts, MSC3773 per-thread counts).
//! A line-for-line port of Tin Hat Web's `src/features/chat/threads/core.ts`. Both replay
//! `testvectors/threads/vectors.json` (a byte-identical copy in both repos, generated by an independent reference:
//! `scripts/threads-oracle.py`). Pure: no Qt, no I/O. docs/THREADS.md has the design.

use serde_json::{json, Value};

pub const THREAD_REL: &str = "m.thread";
pub const THREAD_REL_UNSTABLE: &str = "io.element.thread";
pub const SEP: &str = " \u{b7} ";

/// The thread root an event's content puts it in, or "". Reads the stable and the unstable (old Element) name.
pub fn thread_of(content: &Value) -> String {
    let Some(rel) = content.get("m.relates_to").filter(|r| r.is_object()) else {
        return String::new();
    };
    match rel.get("rel_type").and_then(|t| t.as_str()) {
        Some(THREAD_REL) | Some(THREAD_REL_UNSTABLE) => {}
        _ => return String::new(),
    }
    rel.get("event_id").and_then(|e| e.as_str()).unwrap_or("").to_string()
}

/// Any other relation (edit, reaction, reference): the event it points at, or "".
pub fn relation_target(content: &Value) -> String {
    let Some(rel) = content.get("m.relates_to").filter(|r| r.is_object()) else {
        return String::new();
    };
    if !rel.get("rel_type").map(|t| t.is_string()).unwrap_or(false) {
        return String::new();
    }
    rel.get("event_id").and_then(|e| e.as_str()).unwrap_or("").to_string()
}

fn event_id(e: &Value) -> &str {
    e.get("event_id").and_then(|i| i.as_str()).unwrap_or("")
}

/// Per event (same order): the thread it belongs to ("" = the main timeline). Pass 1: its own m.thread relation.
/// Pass 2: an edit / reaction / reference of an event in a thread is in that thread (one hop, like the server).
/// `events` are raw event JSON objects (`event_id`, `content`).
pub fn thread_ids(events: &[Value]) -> Vec<String> {
    let null = Value::Null;
    let mut direct: std::collections::HashMap<&str, String> = std::collections::HashMap::new();
    for e in events {
        direct.insert(event_id(e), thread_of(e.get("content").unwrap_or(&null)));
    }
    let mut out = Vec::with_capacity(events.len());
    for e in events {
        let mut t = direct.get(event_id(e)).cloned().unwrap_or_default();
        if t.is_empty() {
            let tgt = relation_target(e.get("content").unwrap_or(&null));
            if !tgt.is_empty() {
                t = direct.get(tgt.as_str()).cloned().unwrap_or_default();
            }
        }
        out.push(t);
    }
    out
}

/// m.relates_to for a reply to `parent_id`. A07.3: a parent in a thread keeps the reply in that thread.
pub fn reply_relation(parent_id: &str, parent_thread: &str) -> Value {
    if !parent_thread.is_empty() {
        return json!({ "rel_type": THREAD_REL, "event_id": parent_thread, "is_falling_back": false, "m.in_reply_to": { "event_id": parent_id } });
    }
    json!({ "m.in_reply_to": { "event_id": parent_id } })
}

/// m.relates_to for a message from the thread composer: the spec's fallback reply to the thread's latest event, so
/// clients without threads show it as a normal reply.
pub fn thread_relation(root: &str, latest: &str) -> Value {
    json!({ "rel_type": THREAD_REL, "event_id": root, "is_falling_back": true,
            "m.in_reply_to": { "event_id": if latest.is_empty() { root } else { latest } } })
}

#[derive(Clone, Debug, PartialEq)]
pub struct ReplyRef {
    pub id: String,
    pub sender: String,
    pub ts: i64,
    pub redacted: bool,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Bundle {
    pub count: i64,
    pub latest: ReplyRef,
    pub participated: bool,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Summary {
    pub count: i64,
    pub last_id: String,
    pub last_sender: String,
    pub last_ts: i64,
    pub repliers: Vec<String>,
    pub mine: bool,
}

impl Summary {
    /// The vectors' JSON shape (the web's object).
    pub fn to_json(&self) -> Value {
        json!({ "count": self.count, "lastId": self.last_id, "lastSender": self.last_sender, "lastTs": self.last_ts,
                "repliers": self.repliers, "mine": self.mine })
    }
}

fn newer(a: &ReplyRef, b: &ReplyRef) -> bool {
    if a.ts != b.ts {
        return a.ts > b.ts;
    }
    a.id > b.id
}

/// The thread's summary from the server's bundled aggregation (unsigned m.relations m.thread) merged with the thread
/// events seen since. None = no (visible) replies.
pub fn summarize(bundle: Option<&Bundle>, seen: &[ReplyRef], me: &str) -> Option<Summary> {
    let mut live: Vec<ReplyRef> = Vec::new();
    let mut ids: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut gone: std::collections::HashSet<String> = std::collections::HashSet::new();
    for s in seen {
        if s.redacted {
            gone.insert(s.id.clone());
            continue;
        }
        if ids.contains(&s.id) {
            continue;
        }
        ids.insert(s.id.clone());
        live.push(s.clone());
    }
    let mut cands: Vec<ReplyRef> = live.clone();
    let count: i64;
    let mut mine: bool;
    if let Some(b) = bundle {
        let lat = &b.latest;
        let extra = live.iter().filter(|s| s.ts > lat.ts && s.id != lat.id).count() as i64;
        // a bundle whose latest reply has been deleted since: that reply no longer counts and never shows
        let base = if gone.contains(&lat.id) { b.count - 1 } else { b.count };
        count = (base + extra).max(live.len() as i64);
        if !ids.contains(&lat.id) && !gone.contains(&lat.id) {
            cands.push(ReplyRef { id: lat.id.clone(), sender: lat.sender.clone(), ts: lat.ts, redacted: false });
        }
        mine = b.participated;
    } else {
        count = live.len() as i64;
        mine = false;
    }
    if count == 0 || cands.is_empty() {
        return None;
    }
    let mut last = &cands[0];
    for c in &cands[1..] {
        if newer(c, last) {
            last = c;
        }
    }
    let mut order: Vec<&ReplyRef> = cands.iter().collect();
    order.sort_by(|a, b| b.ts.cmp(&a.ts).then_with(|| a.id.cmp(&b.id)));
    let mut repliers: Vec<String> = Vec::new();
    for c in order {
        if !repliers.contains(&c.sender) {
            repliers.push(c.sender.clone());
        }
        if repliers.len() == 3 {
            break;
        }
    }
    mine = mine || live.iter().any(|s| s.sender == me);
    Some(Summary { count, last_id: last.id.clone(), last_sender: last.sender.clone(), last_ts: last.ts, repliers, mine })
}

/// Relative age, integer maths only (no time zone): both apps print the same bytes.
pub fn rel_time(d: i64) -> String {
    if d < 60000 {
        return "just now".into();
    }
    let m = d / 60000;
    if m < 60 {
        return format!("{m} min ago");
    }
    let h = m / 60;
    if h < 24 {
        return format!("{h} h ago");
    }
    let days = h / 24;
    if days == 1 {
        return "yesterday".into();
    }
    if days < 7 {
        return format!("{days} days ago");
    }
    if days < 365 {
        return format!("{} wk ago", days / 7);
    }
    format!("{} yr ago", days / 365)
}

pub fn count_text(n: i64) -> String {
    if n == 1 {
        "1 reply".into()
    } else {
        format!("{n} replies")
    }
}

/// The line under a thread root: "12 replies · Ana · 5 min ago".
pub fn summary_text(count: i64, name: &str, ts: i64, now: i64) -> String {
    format!("{}{SEP}{name}{SEP}{}", count_text(count), rel_time(now - ts))
}

/// The same for screen readers: "12 replies, last from Ana 5 min ago. Open thread".
pub fn summary_label(count: i64, name: &str, ts: i64, now: i64) -> String {
    format!("{}, last from {name} {}. Open thread", count_text(count), rel_time(now - ts))
}

#[derive(Clone, Debug, PartialEq)]
pub struct MyReceipt {
    pub event_id: String,
    pub ts: i64,
    /// "" = unthreaded, "main", or a thread root
    pub thread: String,
}

/// Unread replies in one thread. `known` = the loaded events (id, ts) (root included); `receipts` = mine: an
/// unthreaded one or this thread's count, "main" and other threads' don't. A receipt reads up to the ts of the event
/// it points at; when that event isn't loaded, only this thread's own receipt counts (by its own ts); my own reply
/// reads everything before it.
pub fn thread_unread(root: &str, known: &[(String, i64)], replies: &[ReplyRef], me: &str, receipts: &[MyReceipt]) -> i64 {
    let ts_of: std::collections::HashMap<&str, i64> = known.iter().map(|(i, t)| (i.as_str(), *t)).collect();
    let mut mark = 0i64;
    for r in receipts {
        if !r.thread.is_empty() && r.thread != root {
            continue;
        }
        let t = match ts_of.get(r.event_id.as_str()) {
            Some(t) => *t,
            None if r.thread == root => r.ts, // this thread's own receipt on a reply not loaded: its time is the best bound
            None => continue,                 // an unthreaded receipt on an event not loaded says nothing about this thread
        };
        if t > mark {
            mark = t;
        }
    }
    for r in replies {
        if r.sender == me && !r.redacted && r.ts > mark {
            mark = r.ts;
        }
    }
    replies.iter().filter(|r| r.sender != me && !r.redacted && r.ts > mark).count() as i64
}

#[derive(Clone, Debug, PartialEq)]
pub struct ListThread {
    pub root: String,
    pub root_sender: String,
    pub last_ts: i64,
    pub mine: bool,
}

/// The Threads list: "all" or "mine" (I wrote the root or replied), newest activity first, ties by root id.
pub fn thread_list(threads: &[ListThread], filter: &str, me: &str) -> Vec<String> {
    let mut keep: Vec<&ListThread> = threads.iter().filter(|t| filter == "all" || t.mine || t.root_sender == me).collect();
    keep.sort_by(|a, b| b.last_ts.cmp(&a.last_ts).then_with(|| a.root.cmp(&b.root)));
    keep.into_iter().map(|t| t.root.clone()).collect()
}

/// Where a main-timeline ("main") receipt may point: the newest event not in a thread, and never a relation whose
/// target isn't among these events (it may be in a thread). The server refuses a main receipt on a threaded event.
/// "" = none.
pub fn main_receipt_target(events: &[Value]) -> String {
    let null = Value::Null;
    let ids = thread_ids(events);
    let known: std::collections::HashSet<&str> = events.iter().map(event_id).collect();
    for i in (0..events.len()).rev() {
        if !ids[i].is_empty() {
            continue;
        }
        let tgt = relation_target(events[i].get("content").unwrap_or(&null));
        if !tgt.is_empty() && !known.contains(tgt.as_str()) {
            continue;
        }
        return event_id(&events[i]).to_string();
    }
    String::new()
}

/// A message notification's text: "Ana (in thread): …" in a group, "In thread: …" in a DM.
pub fn note_text(name: &str, text: &str, in_thread: bool, is_dm: bool) -> String {
    if is_dm {
        return if in_thread { format!("In thread: {text}") } else { text.to_string() };
    }
    format!("{name}{}: {text}", if in_thread { " (in thread)" } else { "" })
}

/// JavaScript's encodeURIComponent: UTF-8, upper-case hex; A-Z a-z 0-9 - _ . ! ~ * ' ( ) kept.
fn enc(x: &str) -> String {
    let mut out = String::with_capacity(x.len());
    for b in x.bytes() {
        let c = b as char;
        if c.is_ascii_alphanumeric() || "-_.!~*'()".contains(c) {
            out.push(c);
        } else {
            out.push_str(&format!("%{b:02X}"));
        }
    }
    out
}

/// The web address of a thread — the shells' push clicks and deep links (docs/THREADS.md "Deep link"):
/// `#/room/<room>[/<event>]?thread=<root>`; an event equal to the root, or empty, is left out. The web's threadLink.
pub fn thread_link(room: &str, root: &str, event: &str) -> String {
    let ev = if !event.is_empty() && event != root { format!("/{}", enc(event)) } else { String::new() };
    format!("#/room/{}{ev}?thread={}", enc(room), enc(root))
}

/// 12.1.16 fix 1-3: what a room coming on screen (or a mention arriving while it is) marks seen in the Mentions list:
/// the mentions (event, ts ms, thread "" = main) whose own timeline is shown and that are no newer than `up_to`. A
/// thread's mention is not seen because the room's main timeline is. (Mark as read stays room-wide; not this rule.)
/// The web's seenOnAttend.
pub fn seen_on_attend(mentions: &[(String, f64, String)], shown: &[String], up_to: f64) -> Vec<String> {
    mentions.iter().filter(|(_, t, th)| *t <= up_to && shown.iter().any(|s| s == th)).map(|(e, _, _)| e.clone()).collect()
}

/// A reply reference from vector / wire JSON ({id, sender, ts, redacted?}).
pub fn reply_ref(v: &Value) -> ReplyRef {
    ReplyRef {
        id: v.get("id").and_then(|x| x.as_str()).unwrap_or("").to_string(),
        sender: v.get("sender").and_then(|x| x.as_str()).unwrap_or("").to_string(),
        ts: v.get("ts").and_then(|x| x.as_i64()).unwrap_or(0),
        redacted: v.get("redacted").and_then(|x| x.as_bool()).unwrap_or(false),
    }
}

/// The server's bundled thread aggregation of a root event (`unsigned["m.relations"]["m.thread"]`), if any.
/// Sender and ts of `latest_event` are readable even when it is still encrypted.
pub fn bundle_of(event: &Value) -> Option<Bundle> {
    // (a JSON number that isn't an integer reads as 0, like the oracle)
    let t = event.get("unsigned")?.get("m.relations")?.get(THREAD_REL)?;
    let latest = t.get("latest_event").filter(|l| l.is_object())?;
    Some(Bundle {
        count: t.get("count").and_then(|c| c.as_i64()).unwrap_or(0),
        latest: ReplyRef {
            id: event_id(latest).to_string(),
            sender: latest.get("sender").and_then(|s| s.as_str()).unwrap_or("").to_string(),
            ts: latest.get("origin_server_ts").and_then(|s| s.as_i64()).unwrap_or(0),
            redacted: false,
        },
        participated: t.get("current_user_participated").and_then(|p| p.as_bool()).unwrap_or(false),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn vectors() -> Value {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../testvectors/threads/vectors.json");
        serde_json::from_str(&std::fs::read_to_string(path).expect("vectors")).expect("json")
    }

    fn strs(v: &Value) -> Vec<String> {
        v.as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect()
    }

    #[test]
    fn constants() {
        let v = vectors();
        assert_eq!(v["constants"]["thread"], json!(THREAD_REL));
        assert_eq!(v["constants"]["thread_unstable"], json!(THREAD_REL_UNSTABLE));
        assert_eq!(v["constants"]["sep"], json!(SEP));
    }

    #[test]
    fn thread_of_vectors() {
        let v = vectors();
        let cases = v["thread_of"].as_array().unwrap();
        assert!(cases.len() >= 8);
        for c in cases {
            assert_eq!(thread_of(&c["content"]), c["out"].as_str().unwrap(), "{}", c["name"]);
        }
    }

    #[test]
    fn thread_ids_vectors() {
        let v = vectors();
        for c in v["thread_ids"].as_array().unwrap() {
            assert_eq!(thread_ids(c["events"].as_array().unwrap()), strs(&c["out"]), "{}", c["name"]);
        }
    }

    #[test]
    fn relation_shapes_vectors() {
        let v = vectors();
        for c in v["reply_relation"].as_array().unwrap() {
            assert_eq!(reply_relation(c["parent"].as_str().unwrap(), c["parentThread"].as_str().unwrap()), c["out"], "{}", c["name"]);
        }
        for c in v["thread_relation"].as_array().unwrap() {
            assert_eq!(thread_relation(c["root"].as_str().unwrap(), c["latest"].as_str().unwrap()), c["out"], "{}", c["name"]);
        }
    }

    #[test]
    fn summarize_vectors() {
        let v = vectors();
        for c in v["summarize"].as_array().unwrap() {
            let bundle = if c["bundle"].is_null() {
                None
            } else {
                Some(Bundle {
                    count: c["bundle"]["count"].as_i64().unwrap(),
                    latest: reply_ref(&c["bundle"]["latest"]),
                    participated: c["bundle"]["participated"].as_bool().unwrap_or(false),
                })
            };
            let seen: Vec<ReplyRef> = c["seen"].as_array().unwrap().iter().map(reply_ref).collect();
            let got = summarize(bundle.as_ref(), &seen, c["me"].as_str().unwrap()).map(|s| s.to_json()).unwrap_or(Value::Null);
            assert_eq!(got, c["out"], "{}", c["name"]);
        }
    }

    #[test]
    fn summary_text_vectors() {
        let v = vectors();
        for c in v["summary_text"].as_array().unwrap() {
            let (n, name, ts, now) = (c["count"].as_i64().unwrap(), c["name"].as_str().unwrap(), c["ts"].as_i64().unwrap(), c["now"].as_i64().unwrap());
            assert_eq!(summary_text(n, name, ts, now), c["text"].as_str().unwrap());
            assert_eq!(summary_label(n, name, ts, now), c["label"].as_str().unwrap());
        }
    }

    #[test]
    fn thread_unread_vectors() {
        let v = vectors();
        for c in v["thread_unread"].as_array().unwrap() {
            let known: Vec<(String, i64)> =
                c["known"].as_array().unwrap().iter().map(|k| (k["id"].as_str().unwrap().to_string(), k["ts"].as_i64().unwrap())).collect();
            let replies: Vec<ReplyRef> = c["replies"].as_array().unwrap().iter().map(reply_ref).collect();
            let receipts: Vec<MyReceipt> = c["receipts"]
                .as_array()
                .unwrap()
                .iter()
                .map(|r| MyReceipt {
                    event_id: r["eventId"].as_str().unwrap().to_string(),
                    ts: r["ts"].as_i64().unwrap(),
                    thread: r["thread"].as_str().unwrap().to_string(),
                })
                .collect();
            assert_eq!(
                thread_unread(c["root"].as_str().unwrap(), &known, &replies, c["me"].as_str().unwrap(), &receipts),
                c["out"].as_i64().unwrap(),
                "{}",
                c["name"]
            );
        }
    }

    #[test]
    fn thread_list_vectors() {
        let v = vectors();
        for c in v["thread_list"].as_array().unwrap() {
            let threads: Vec<ListThread> = c["threads"]
                .as_array()
                .unwrap()
                .iter()
                .map(|t| ListThread {
                    root: t["root"].as_str().unwrap().to_string(),
                    root_sender: t["rootSender"].as_str().unwrap().to_string(),
                    last_ts: t["lastTs"].as_i64().unwrap(),
                    mine: t["mine"].as_bool().unwrap(),
                })
                .collect();
            assert_eq!(thread_list(&threads, c["filter"].as_str().unwrap(), c["me"].as_str().unwrap()), strs(&c["out"]), "{}", c["name"]);
        }
    }

    #[test]
    fn main_receipt_target_vectors() {
        let v = vectors();
        for c in v["main_receipt_target"].as_array().unwrap() {
            assert_eq!(main_receipt_target(c["events"].as_array().unwrap()), c["out"].as_str().unwrap(), "{}", c["name"]);
        }
    }

    #[test]
    fn seen_on_attend_vectors() {
        let v = vectors();
        let cases = v["seen_on_attend"].as_array().unwrap();
        assert!(cases.len() >= 5);
        for c in cases {
            let ms: Vec<(String, f64, String)> = c["mentions"]
                .as_array()
                .unwrap()
                .iter()
                .map(|m| (m["e"].as_str().unwrap().to_string(), m["t"].as_f64().unwrap(), m["thread"].as_str().unwrap().to_string()))
                .collect();
            let shown: Vec<String> = c["shown"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
            let out: Vec<String> = c["out"].as_array().unwrap().iter().map(|x| x.as_str().unwrap().to_string()).collect();
            assert_eq!(seen_on_attend(&ms, &shown, c["upTo"].as_f64().unwrap()), out, "{}", c["name"]);
        }
    }

    #[test]
    fn note_text_vectors() {
        let v = vectors();
        for c in v["note_text"].as_array().unwrap() {
            assert_eq!(
                note_text(c["sender"].as_str().unwrap(), c["text"].as_str().unwrap(), c["inThread"].as_bool().unwrap(), c["isDm"].as_bool().unwrap()),
                c["out"].as_str().unwrap(),
                "{}",
                c["name"]
            );
        }
    }

    #[test]
    fn thread_link_vectors() {
        let v = vectors();
        let cases = v["thread_link"].as_array().unwrap();
        assert!(cases.len() >= 5);
        for c in cases {
            assert_eq!(thread_link(c["room"].as_str().unwrap(), c["root"].as_str().unwrap(), c["event"].as_str().unwrap()), c["out"].as_str().unwrap(), "{}", c["name"]);
        }
    }

    #[test]
    fn bundle_of_vectors() {
        let v = vectors();
        for c in v["bundle_of"].as_array().unwrap() {
            let got = bundle_of(&c["event"])
                .map(|b| json!({"count": b.count, "latest": {"id": b.latest.id, "sender": b.latest.sender, "ts": b.latest.ts}, "participated": b.participated}))
                .unwrap_or(Value::Null);
            assert_eq!(got, c["out"], "{}", c["name"]);
        }
    }
}
